#!/usr/bin/env node
// Rebuilds the generated files of the ICM system map (never hand-edit them):
//   map/objects/_index.md   one line per object card, from each card's frontmatter
//   map/AGENTS.md           identical copy of map/CLAUDE.md for non-Claude agents
//   map/routing.md          identical copy of map/CLAUDE.md
// Run from the repo root: node map/_meta/build-index.mjs   (or `npm run map:sync` in web/)
// Pass --check to exit 1 when a generated file is out of date instead of writing it.
import { readdirSync, readFileSync, writeFileSync, statSync } from "node:fs";
import { join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(fileURLToPath(import.meta.url), "..", "..", "..");
const mapDir = join(root, "map");
const check = process.argv.includes("--check");
let stale = 0;

function frontmatter(text) {
  const m = text.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  const out = {};
  if (!m) return out;
  for (const line of m[1].split(/\r?\n/)) {
    const kv = line.match(/^([a-z_]+):\s*(.*)$/);
    if (kv) out[kv[1]] = kv[2].trim();
  }
  return out;
}

function title(text) {
  const m = text.match(/^# (.+)$/m);
  return m ? m[1].trim() : "(untitled)";
}

function walk(dir) {
  const files = [];
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) files.push(...walk(p));
    else if (name.endsWith(".md") && !name.startsWith("_")) files.push(p);
  }
  return files.sort();
}

function emit(path, content) {
  const current = (() => { try { return readFileSync(path, "utf8"); } catch { return null; } })();
  if (current === content) return;
  if (check) { console.error(`out of date: ${relative(root, path)}`); stale++; return; }
  writeFileSync(path, content);
  console.log(`wrote ${relative(root, path)}`);
}

// 1. objects/_index.md
const objectsDir = join(mapDir, "objects");
const rows = [];
for (const file of walk(objectsDir)) {
  const text = readFileSync(file, "utf8");
  const fm = frontmatter(text);
  const rel = relative(objectsDir, file).split(sep).join("/");
  rows.push({ cluster: fm.cluster ?? rel.split("/")[0], rel, title: title(text), universe: fm.universe ?? "?", status: fm.status ?? "?", entity: fm.entity ?? "" });
}
rows.sort((a, b) => a.cluster.localeCompare(b.cluster) || a.rel.localeCompare(b.rel));
let index = "# Objects — index\n\nGenerated by `node map/_meta/build-index.mjs`. One line per card. Do not edit by hand.\n\n";
let cluster = null;
for (const r of rows) {
  if (r.cluster !== cluster) { cluster = r.cluster; index += `\n## ${cluster}\n\n| Card | Universe | Status | Owning file |\n|---|---|---|---|\n`; }
  index += `| [${r.title}](${r.rel}) | ${r.universe} | ${r.status} | ${r.entity ? "`" + r.entity + "`" : ""} |\n`;
}
emit(join(objectsDir, "_index.md"), index);

// 2. AGENTS.md and routing.md copies of CLAUDE.md
const entry = readFileSync(join(mapDir, "CLAUDE.md"), "utf8");
const banner = "<!-- Generated copy of map/CLAUDE.md by map/_meta/build-index.mjs. Edit CLAUDE.md, then run the script. -->\n";
emit(join(mapDir, "AGENTS.md"), banner + entry);
emit(join(mapDir, "routing.md"), banner + entry);

if (check && stale) process.exit(1);
console.log(check ? "map is current" : `index: ${rows.length} object cards`);
